/// <summary>
/// Bug 275352: CB411- Vendor auto charges not getting copied to sales lines (DIsc1 and Disc2) if created through CT
/// Method to make pending vendor invoice line off remit charge codes not editable
/// </summary>
/// <param name = "_hasVendorInvoice">A Boolean value indicating whether the misc. charge is connected to a purchase order invoice</param>
/// <param name = "_isCallerDatasourceEditable">A Boolean value indicating whether the calling datasource is editable</param>
/// <returns>true if the <c>MarkupTrans</c> record can be edited; otherwise, false.</returns>
boolean editingAllowed(boolean _hasVendorInvoice, boolean _isCallerDatasourceEditable)
{
    boolean editing = next editingAllowed(_hasVendorInvoice, _isCallerDatasourceEditable);

    if (editing
    &&  this.ModuleCategory == HeadingLine::Line
    &&  this.ModuleType     == MarkupModuleType::Vend
    &&  this.TransTableId   == tableNum(VendInvoiceInfoLine)
        &&  MarkupTable::find(this.ModuleType, this.MarkupCode).METIsOffRemittance)
    {
        editing = false;
    }

    return editing;
}

/// <summary>
/// Chain-of-command for table insert.
/// Place MET-specific pre/post insert logic here.
/// </summary>
public void insert(SourceDocumentLineAccountingStatus _targetAccountingStatus)
{   
    // Always call base first
    next insert(_targetAccountingStatus);
    this.updateCalculatedAmountByWeight();
}

/// <summary>
/// Chain-of-command for table update.
/// Place MET-specific pre/post update logic here.
/// </summary>
public void update(boolean _updateMiscMatching, boolean _isEditingBlockedByVendorInvoice)
{
    // Always call base first
    next update(_updateMiscMatching, _isEditingBlockedByVendorInvoice);
    this.updateCalculatedAmountByWeight();
}

/// <summary>
/// Update CalculatedAmount from METSalesLinePriceComponentTmp.ExtValue.
/// If _force is false, only set when CalculatedAmount == 0 (no existing value).
/// If _force is true, overwrite regardless.
/// Adjust field names if your MET temp table uses different names.
/// </summary>
private void updateCalculatedAmountByWeight()
{
    CustInvoiceTrans custInvoiceTrans;
    METWHSPhysDimUOMSite metWHSPhysDimUOMSite;
    InventDim inventDim;
    real actualWeight;

    // Fetch related invoice line
    select firstonly ItemId, Qty, SalesUnit, InventDimId
    from custInvoiceTrans
    where custInvoiceTrans.RecId == this.TransRecId;

    if (!custInvoiceTrans.RecId)
    {
        return;
    }


    // Cache flag (avoid repeated static calls)
    boolean isPricedByWeight = METPricedByWeightCache::getPricedByWeightAttributeCached(custInvoiceTrans.ItemId);
    boolean isCWItem = PdsGlobal::pdsIsCWItem(custInvoiceTrans.ItemId);

    // Check priced by weight
    if (!isPricedByWeight)
    {
        return;
    }

    inventDim = InventDim::find(custInvoiceTrans.InventDimId);

    // Fetch weight setup
    select firstonly NetWeight
    from metWHSPhysDimUOMSite
    where metWHSPhysDimUOMSite.ItemId == custInvoiceTrans.ItemId
       && metWHSPhysDimUOMSite.UOM    == custInvoiceTrans.SalesUnit
       && metWHSPhysDimUOMSite.SiteId == inventDim.InventSiteId;

    if (!metWHSPhysDimUOMSite.RecId || metWHSPhysDimUOMSite.NetWeight == 0)
    {
        return;
    }


    // If priced by weight but not CW, multiply qty by NetWeight
    actualWeight = (!isCWItem && isPricedByWeight)
            ? custInvoiceTrans.inventQty * metWHSPhysDimUOMSite.NetWeight
            : custInvoiceTrans.inventQty;

    if (!actualWeight)
    {
        return;
    }

    // Avoid unnecessary update
    real newAmount = this.Value * actualWeight;

    if (this.CalculatedAmount == newAmount)
    {
        return;
    }

    ttsbegin;

    this.skipDataMethods(true);
    this.CalculatedAmount = newAmount;
    this.doUpdate();
    this.skipDataMethods(false);

    ttscommit;
}
